import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int a = sc.nextInt();
        int l = sc.nextInt();
        int n = sc.nextInt();

        int bestId = -1;
        int minArea = Integer.MAX_VALUE;

        for (int i = 1; i <= n; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();

            boolean fits = (a <= x && l <= y) || (a <= y && l <= x);
            if (fits) {
                int area = x * y;
                if (area < minArea) {
                    minArea = area;
                    bestId = i;
                }
            }
        }

        System.out.println(bestId);
    }
}
